        public static Packet UserLoginOK(bool reconnected, SAccountInfo accountInfo, vectorCharacterInfoLogins characterDataList)
        {
            Packet stream = new Packet();
            stream.WriteInt(0);
            stream.WriteShort(0);
            stream.WriteInt(ProtocolGame_METHOD.uMethodID_UserLoginOK);
            stream.WriteBool(reconnected);
            SAccountInfo.Write(stream, accountInfo);
            vectorCharacterInfoLogins.Write(stream, characterDataList);
            stream.Patch(stream.get_used_size() - 6, 0);
            return stream;
        }

        public static Packet UserLoginFailed(EServerErrorType error)
        {
            Packet stream = new Packet();
            stream.WriteInt(0);
            stream.WriteShort(0);
            stream.WriteInt(ProtocolGame_METHOD.uMethodID_UserLoginFailed);
            EServerErrorType.Write(stream, error);
            stream.Patch(stream.get_used_size() - 6, 0);
            return stream;
        }

